/**
 * [Process Market Data - Structured Analysis]
 * Input: Merged data from Aggregate node and original request
 */

// --- Helper Function for Name Resolution ---
/**
 * Resolves an ID to a name, using Redis first, then ESI as a fallback.
 * Caches ESI results back to Redis.
 * @param {string|number} id - The EVE ID (item, station, structure)
 * @param {'item'|'location'} type - The type of ID
 * @param {object} redis - The ioredis client instance
 * @param {object} helpers - The n8n 'this.helpers' object
 * @returns {Promise<string>} - The resolved name
 */
async function resolveName(id, type, redis, helpers) {
  if (!id || id === 'Unknown' || id === null) {
    return 'Unknown';
  }

  const idStr = String(id);

  // 1. Try Redis first
  try {
    let name = await redis.hget('eve:id_to_name', idStr);
    if (name) {
      return name;
    }
  } catch (e) {
    console.error(`Redis hget error for ${idStr}: ${e.message}`);
  }

  // 2. Not in Redis, try ESI
  console.log(`[Cache MISS] ID ${idStr}. Fetching from ESI...`);
  let esiUrl = '';
  let defaultName = 'Unknown';

  if (type === 'item') {
    esiUrl = `https://esi.evetech.net/latest/universe/types/${idStr}/`;
    defaultName = 'Unknown Item';
  } else if (type === 'location') {
    const numericId = Number(idStr);
    // NPC Stations IDs are generally < 1,000,000,000
    if (numericId && numericId < 1000000000) { 
      esiUrl = `https://esi.evetech.net/latest/universe/stations/${idStr}/`;
      defaultName = 'Unknown Station';
    } else {
      // It's a player structure (requires auth) or invalid
      defaultName = 'Unknown (Structure)';
    }
  }

  // 3. Make ESI request if we have a URL
  if (esiUrl) {
    try {
      const options = {
        url: esiUrl,
        headers: { 'User-Agent': 'EVE-Alfred-Bot/2.1 - Name Resolution' },
        json: true, // Automatically parse JSON response
        timeout: 5000 // 5-second timeout
      };
      // Use n8n's built-in helper for HTTP requests
      const response = await helpers.httpRequest(options);

      if (response && response.name) {
        const esiName = response.name;
        console.log(`[ESI OK] ID ${idStr} -> ${esiName}`);

        // 4. Cache the ESI result back into Redis
        try {
          await redis.hset('eve:id_to_name', idStr, esiName);
        } catch (e) {
          console.error(`Redis hset error for ${idStr}: ${e.message}`);
        }
        return esiName;
      }
    } catch (esiError) {
      console.error(`ESI lookup failed for ID ${idStr} at ${esiUrl}:`, esiError.message);
    }
  }

  // Return default if ESI failed or it was a structure
  return defaultName;
}
// --- End Helper Function ---


// --- Main Node Logic ---
try {
  const items = $input.all();
  console.log('Total items received:', items.length);

  // Get the aggregated item
  const aggregatedItem = items[0].json;

  // Request data might be in items[1] or embedded in aggregatedItem
  let requestData;
  if (items.length > 1 && items[1]) {
    requestData = items[1].json;
  } else {
    // Request data is embedded in the aggregated item
    requestData = aggregatedItem;
  }

  // Extract the combined data array
  const combinedData = aggregatedItem.data || [];

  // Separate history from orders based on their structure
  let history = [];
  let orders = [];

  combinedData.forEach(item => {
    // History items have: date, average, highest, lowest, order_count, volume
    if (item.date && item.average !== undefined && item.highest !== undefined) {
      history.push(item);
    }
    // Order items have: order_id, price, is_buy_order, location_id, etc.
    else if (item.order_id !== undefined && item.price !== undefined) {
      orders.push(item);
    }
  });

  console.log(`Parsed ${history.length} history records and ${orders.length} orders`);

  // --- Historical trends ---
  const last7 = history.slice(-7);
  const avg_price_7d = last7.length
    ? last7.reduce((sum, d) => sum + (d.average || 0), 0) / last7.length
    : null;

  const avg_daily_volume = last7.length
    ? last7.reduce((sum, d) => sum + (d.volume || 0), 0) / last7.length
    : null;

  const prices = last7.map(d => d.average).filter(v => v != null);
  const price_change_percent =
    prices.length > 1
      ? ((prices[prices.length - 1] - prices[0]) / prices[0]) * 100
      : null;

  const mean = prices.length ? prices.reduce((a, b) => a + b, 0) / prices.length : 0;
  const variance = prices.length
    ? prices.reduce((sum, p) => sum + Math.pow(p - mean, 2), 0) / prices.length
    : 0;
  const volatility_percent = variance ? Math.sqrt(variance) / mean * 100 : null;

  // --- Current market ---
  const sellOrders = orders.filter(o => !o.is_buy_order);
  const buyOrders = orders.filter(o => o.is_buy_order);

  const sell_price = sellOrders.length
    ? Math.min(...sellOrders.map(o => o.price))
    : null;
  const buy_price = buyOrders.length
    ? Math.max(...buyOrders.map(o => o.price))
    : null;

  const spread_isk = sell_price != null && buy_price != null ? sell_price - buy_price : null;
  const spread_percent = sell_price != null && buy_price != null
    ? (spread_isk / sell_price) * 100
    : null;

  const total_orders = orders.length;

  // --- Locations ---
  const best_sell_order = sellOrders.reduce((best, o) => (!best || o.price < best.price ? o : best), null);
  const best_buy_order = buyOrders.reduce((best, o) => (!best || o.price > best.price ? o : best), null);

  const market_locations = {
    best_sell_location: best_sell_order ? best_sell_order.location_id : 'Unknown',
    best_buy_location: best_buy_order ? best_buy_order.location_id : 'Unknown'
  };

  const raw_data_summary = {
    history_count: history.length,
    total_orders: orders.length,
    first_date: history.length ? history[0].date : null,
    last_date: history.length ? history[history.length - 1].date : null
  };

  // Get region name from the request data
  const regionId = requestData.region_ids?.[0];
  const regionName = requestData.region_name_map?.[regionId] || 'Unknown';
  const typeId = requestData.type_ids?.[0];

  // --- Resolve Names (Redis then ESI) ---
  const Redis = require('ioredis');
  const redis = new Redis({ host: 'redis', port: 6379, db: 0 });
  const helpers = this.helpers; // Get n8n helper functions

  let sellLocationName = 'Unknown';
  let buyLocationName = 'Unknown';
  let itemName = 'Unknown';

  try {
    // Resolve all names using the helper function
    sellLocationName = await resolveName(
      market_locations.best_sell_location, 
      'location', 
      redis, 
      helpers
    );

    buyLocationName = await resolveName(
      market_locations.best_buy_location, 
      'location', 
      redis, 
      helpers
    );

    itemName = await resolveName(
      typeId, 
      'item', 
      redis, 
      helpers
    );

    await redis.quit();
  } catch (lookupError) {
    console.error('Name resolution block error:', lookupError);
    if (redis) await redis.quit();
    // Set defaults on error
    sellLocationName = sellLocationName || 'Lookup Error';
    buyLocationName = buyLocationName || 'Lookup Error';
    itemName = itemName || 'Lookup Error';
  }

  return [{
    json: {
      status: 'success',
      type: 'market_analysis',
      region: regionName,
      region_id: regionId,
      item_name: itemName, // Resolved name
      item_type_id: typeId,
      timestamp: new Date().toISOString(),
      market_summary: {
        sell_price,
        buy_price,
        spread_isk,
        spread_percent,
        total_orders,
        sell_orders_count: sellOrders.length,
        buy_orders_count: buyOrders.length
      },
      market_trends: {
        avg_price_7d,
        avg_daily_volume,
        price_change_percent,
        volatility_percent
      },
      market_locations: {
        best_sell_location: sellLocationName, // Resolved name
        best_sell_location_id: market_locations.best_sell_location,
        best_buy_location: buyLocationName, // Resolved name
        best_buy_location_id: market_locations.best_buy_location
      },
      raw_data_summary
    }
  }];

} catch (err) {
  console.error('Error processing market data:', err);
  return [{
    json: {
      status: 'error',
      action: 'market_analysis',
      error: err.message,
      stack: err.stack
    }
  }];
}

// Always generates both market order and history API calls, ignoring cache misses.
// Automatically handles PLEX global market (region 19000001)

const request = $input.first().json;

let marketOrderCall = null;
let marketHistoryCall = null;

// This logic assumes we only ever ask for one item and region at a time.
let regionId = request.region_ids[0];
const typeId = request.type_ids[0];

// PLEX type ID constant
const PLEX_TYPE_ID = 44992;
const PLEX_GLOBAL_REGION = 19000001;

// Check if this is a PLEX query and override region
let isPlex = false;
if (typeId === PLEX_TYPE_ID) {
    console.log(`[PLEX DETECTED] Original region: ${regionId}, switching to global market: ${PLEX_GLOBAL_REGION}`);
    regionId = PLEX_GLOBAL_REGION;
    isPlex = true;
}

if (regionId && typeId) {
    marketOrderCall = {
        url: `https://esi.evetech.net/latest/markets/${regionId}/orders/?type_id=${typeId}`,
        cache_key: `eve:market:orders:${regionId}:${typeId}`,
        type: 'market_orders'
    };

    marketHistoryCall = {
        url: `https://esi.evetech.net/latest/markets/${regionId}/history/?type_id=${typeId}`,
        cache_key: `eve:market:history:${regionId}:${typeId}`,
        type: 'market_history'
    };
}

console.log(`Generated market_order_call and market_history_call for type ${typeId} in region ${regionId}`);

// Build output with potential PLEX overrides
const output = { 
    ...request, 
    market_order_call: marketOrderCall,
    market_history_call: marketHistoryCall
};

// Add PLEX metadata if applicable
if (isPlex) {
    output.is_plex_global_market = true;
    output.original_region_id = request.region_ids[0];
    output.region_ids = [PLEX_GLOBAL_REGION];

    // Update region name map
    output.region_name_map = {
        ...request.region_name_map,
        [PLEX_GLOBAL_REGION]: 'PLEX Global Market'
    };

    // Update cache keys
    output.cache_keys = [
        `eve:market:orders:${PLEX_GLOBAL_REGION}:${typeId}`,
        `eve:market:history:${PLEX_GLOBAL_REGION}:${typeId}`
    ];
}

// Return a single item with the new call objects
return [{ json: output }];

// Validate, resolve names, and set defaults for the market request.
const Redis = require('ioredis');
let redis;

try {
  redis = new Redis({ host: 'redis', port: 6379, db: 0, connectTimeout: 2000 });
  await new Promise((resolve, reject) => {
    redis.on('ready', resolve);
    redis.on('error', reject);
  });

  const input = $input.first().json;

  // 1. Normalize the 'items' input (handles string or array of strings)
  let itemNamesFromInput = [];
  if (typeof input.items === 'string' && input.items.trim() !== '') {
    itemNamesFromInput = [input.items];
  } else if (Array.isArray(input.items)) {
    itemNamesFromInput = input.items.filter(item => typeof item === 'string' && item.trim() !== '');
  }

  if (itemNamesFromInput.length === 0) {
    throw new Error("Input 'items' is required and must be a non-empty string or an array of non-empty strings.");
  }

  // The action is now implicitly 'market_analysis' for a "FULL" lookup.
  const action = 'market_analysis';

  // 2. Set defaults
  // Default to The Forge (Jita) if no region_ids are provided
  const regionIds = input.region_ids && Array.isArray(input.region_ids) && input.region_ids.length > 0 ? input.region_ids : [10000002]; 

  // 3. Resolve item names to IDs and region IDs to names from Redis
  const resolvedIds = [];
  const unresolvedItems = [];
  const regionNameMap = {};

  const nameToIdPipeline = redis.pipeline();
  // Using 'eve:name_to_id' hash which maps lowercase names to IDs
  // NEW: Try to clean up names before lookup
  itemNamesFromInput.forEach(originalName => {
    let processedName = originalName.trim();

    // RULE: Remove ' ore' from the end, case-insensitive
    if (processedName.toLowerCase().endsWith(' ore')) {
      processedName = processedName.substring(0, processedName.length - 4).trim();
    }

    // Add more cleaning rules here if needed

    // Lookup the processed name
    nameToIdPipeline.hget('eve:name_to_id', processedName.toLowerCase());
  });

  const regionIdToNamePipeline = redis.pipeline();
  // Using 'eve:id_to_name' for region names for consistency
  regionIds.forEach(id => regionIdToNamePipeline.hget('eve:id_to_name', id));

  const [nameResults, regionNameResults] = await Promise.all([
    nameToIdPipeline.exec(),
    regionIdToNamePipeline.exec()
  ]);

  // Process item name resolution results
  nameResults.forEach(([err, id], index) => {
    if (id) {
      resolvedIds.push(parseInt(id, 10));
    } else {
      // Use the *original* name for the unresolved list
      unresolvedItems.push(itemNamesFromInput[index]);
    }
  });

  // Process region name resolution results
  regionNameResults.forEach(([err, name], index) => {
    if (name) {
      regionNameMap[regionIds[index]] = name;
    }
  });

  const finalTypeIds = [...new Set(resolvedIds)];

  // REMOVED: We no longer throw an error if no items are resolved.
  // The workflow will simply continue with an empty type_ids list
  // and a populated unresolved_items list.

  // 4. Prepare the request object for the rest of the workflow
  const request = {
    action: action, // Hardcoded for a full lookup
    type_ids: finalTypeIds,
    region_ids: regionIds,
    unresolved_items: unresolvedItems,
    region_name_map: regionNameMap,
    force_refresh: input.force_refresh || false,
    timestamp: new Date().toISOString()
  };

  // 5. Generate cache keys for the 'market_analysis' action
  const cacheKeys = [];
  for (const regionId of request.region_ids) {
    for (const typeId of request.type_ids) {
      // 'market_analysis' requires both orders and history
      cacheKeys.push(`eve:market:orders:${regionId}:${typeId}`);
      cacheKeys.push(`eve:market:history:${regionId}:${typeId}`);
    }
  }

  request.cache_keys = [...new Set(cacheKeys)];

  return [{ json: request }];

} catch (error) {
  console.error('❌ Input validation/resolution failed:', error.message, error.stack);
  // Re-throw to halt execution and report error clearly
  throw error;
} finally {
  if (redis) await redis.quit();
}
